Correct approach:
```javascript
app.post('/refresh', async (req, res) => {
  const { refreshToken } = req.cookies;
  if (!refreshToken) return res.sendStatus(401);
  const payload = verifyToken(refreshToken);
  const storedToken = await redis.get(`refresh:${payload.userId}`);
  if (storedToken !== refreshToken) {
    await redis.del(`refresh:${payload.userId}`);
    return res.status(403).json({ error: 'Token reuse detected. Session revoked.' });
  }
  const newAccess = generateAccessToken(payload.userId);
  const newRefresh = generateRefreshToken(payload.userId);
  await redis.set(`refresh:${payload.userId}`, newRefresh, 'EX', 604800);
  res.cookie('refreshToken', newRefresh, { httpOnly: true, secure: true });
  res.json({ accessToken: newAccess });
});
```

Demonstrates safe URL fetching by resolving DNS first, checking against private IP blocks, and pinning the IP address.

```javascript
const dns = require('dns').promises;
const net = require('net');
const axios = require('axios');

async function safeFetch(urlInput) {
  const parsed = new URL(urlInput);
  if (!['http:', 'https:'].includes(parsed.protocol)) throw new Error('Invalid protocol');

  const addresses = await dns.resolve4(parsed.hostname);
  const ip = addresses[0];

  if (net.isIP(ip) && (ip.startsWith('10.') || ip.startsWith('192.168.') || ip === '127.0.0.1')) {
    throw new Error('Access to private IP range denied');
  }

  // Pin the resolved IP to prevent DNS rebinding
  parsed.hostname = ip;
  return axios.get(parsed.toString(), { maxRedirects: 0, headers: { Host: parsed.hostname } });
}
```

